package com.bemo.hr.product.support;import org.springframework.data.jpa.repository.*;import jakarta.persistence.LockModeType;import java.util.*;public interface SupportTicketRepository extends JpaRepository<SupportTicket,String>{Optional<SupportTicket>findByOperationId(String operationId);List<SupportTicket>findAllByOrderByCreatedAtDesc();long countByStatusNotInAndPriorityIn(Collection<String>statuses,Collection<String>priorities);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select t from SupportTicket t where t.id=:id")Optional<SupportTicket>findByIdForUpdate(String id);}
